import math
import base64

class QuantumLattice:
    def __init__(self, x_size, y_size, z_size):
        self.x_size = x_size
        self.y_size = y_size
        self.z_size = z_size
        self.lattice = [[[None for _ in range(z_size)] for _ in range(y_size)] for _ in range(x_size)]

    def populate_lattice(self, data, seed):
        if len(data) > self.x_size * self.y_size * self.z_size:
            raise ValueError("Data exceeds lattice capacity.")
        
        index = 0
        for x in range(self.x_size):
            for y in range(self.y_size):
                for z in range(self.z_size):
                    if index < len(data):
                        # XOR operation to cloak data
                        self.lattice[x][y][z] = chr(ord(data[index]) ^ ord(seed[index % len(seed)]))
                        index += 1
                    else:
                        self.lattice[x][y][z] = '\0'

    def get_encrypted_data(self):
        return ''.join(
            ''.join(
                ''.join(char for char in plane if char != '\0') for plane in row
            ) for row in self.lattice
        )

    def get_decrypted_data(self, seed, original_length):
        decrypted_data = []
        index = 0
        for x in range(self.x_size):
            for y in range(self.y_size):
                for z in range(self.z_size):
                    if index < original_length:
                        # Reverse XOR operation to decrypt
                        decrypted_data.append(
                            chr(ord(self.lattice[x][y][z]) ^ ord(seed[index % len(seed)]))
                        )
                        index += 1
        return ''.join(decrypted_data)

def encrypt(data, seed):
    lattice_size = math.ceil(len(data)**(1/3))
    lattice = QuantumLattice(lattice_size, lattice_size, lattice_size)
    lattice.populate_lattice(data, seed)
    return base64.b64encode(lattice.get_encrypted_data().encode()).decode()

def decrypt(encrypted_data, seed, original_length):
    decoded_data = base64.b64decode(encrypted_data).decode()
    lattice_size = math.ceil(len(decoded_data)**(1/3))
    lattice = QuantumLattice(lattice_size, lattice_size, lattice_size)
    lattice.populate_lattice(decoded_data, seed)
    return lattice.get_decrypted_data(seed, original_length)

