    """Decode lattice into binary."""
    binary = []
    size = lattice.shape[0]

    for x in range(size):
        for y in range(size):
            for z in range(size):
                binary.append('1' if lattice[x, y, z] > 0.5 else '0')
    return ''.join(binary)

